package net.minecraft.world.item;
import java.util.*;
public class ItemStack {
 public static final ItemStack EMPTY=new ItemStack((Item)null,0);
 public final Item item; public int count; public final Map<String,Object> components=new HashMap<>();
 public ItemStack(Item item){this(item,1);} public ItemStack(Item item,int count){this.item=item;this.count=count;}
 public ItemStack(String id,int count){this(net.minecraft.core.registries.BuiltInRegistries.item(id),count);}
 public boolean isEmpty(){return item==null||count<=0;} public Item getItem(){return item;} public int getCount(){return count;}
 public void shrink(int n){count=Math.max(0,count-n);} public ItemStack copy(){var n=new ItemStack(item,count);n.components.putAll(components);return n;}
 public ItemStack split(int n){var part=copy();part.count=Math.min(n,count);shrink(part.count);return part;}
 public static boolean isSameItemSameComponents(ItemStack a,ItemStack b){return a.isEmpty()&&b.isEmpty()||!a.isEmpty()&&!b.isEmpty()&&a.item==b.item&&a.components.equals(b.components);}
}

