/** Models the native split -> ItemEntity -> addFreshEntity return edge, without Mixin weaving. */
public class Containers{
 public static void dropItemStack(Level level,double x,double y,double z,ItemStack output){
  level.dropCalls++;
  while(!output.isEmpty()){
   ItemStack part=output.split(output.getCount());
   Entity entity=level.unrelatedEntity?new Entity(level):new ItemEntity(level,x,y,z,part);
   NasaProductionHarness.spawn(level,entity);
  }
 }
