package net.minecraft.world.item.crafting;
import java.util.*;import net.minecraft.core.registries.BuiltInRegistries;import net.minecraft.tags.TagKey;import net.minecraft.world.item.*;
/** Vanilla getItems cache stays stale across registry tag rebinding by design. */
public final class Ingredient{
 public interface Value{Collection<ItemStack> getItems();}
 public record ItemValue(ItemStack item) implements Value{public Collection<ItemStack> getItems(){return List.of(item);}}
 public record TagValue(TagKey<Item> tag) implements Value{public Collection<ItemStack> getItems(){return BuiltInRegistries.ITEM.getTag(tag).map(t->t.stream().map(h->new ItemStack(h.value())).toList()).orElse(List.of());}}
 private final Value[] values;private final boolean custom;private ItemStack[] cached;
 public Ingredient(Value... values){this.values=values;custom=false;}public Ingredient(boolean custom,Value... values){this.values=values;this.custom=custom;}
 public static Ingredient of(String id){return new Ingredient(new ItemValue(new ItemStack(id,1)));}public static Ingredient of(TagKey<Item> tag){return new Ingredient(new TagValue(tag));}
 public Value[] getValues(){if(custom)throw new IllegalStateException("Cannot retrieve values from custom ingredient!");return values;}
 public boolean isCustom(){return custom;}public boolean isEmpty(){return values.length==0&&!custom;}public boolean isSimple(){return true;}
 public ItemStack[] getItems(){if(cached==null)cached=Arrays.stream(values).flatMap(v->v.getItems().stream()).toArray(ItemStack[]::new);return cached;}
 public boolean test(ItemStack stack){return !stack.isEmpty()&&Arrays.stream(getItems()).anyMatch(value->value.getItem()==stack.getItem());}
}
